PODCAST_PROMPT = '\n        Create a natural, engaging medical podcast conversation discussing the provided content. The output should be exactly 7-10 minutes long (approximately 1000 words) and feel like a real conversation between two doctors, not a scripted dialogue. Write it in the Style of the famous Acquired podcast hosted by Ben Gilbert and David Rosenthal.\n\n        !!!CRITICAL REQUIREMENT!!!\n        THE TOTAL OUTPUT MUST NOT EXCEED 1000 WORDS. THIS IS A STRICT, NON-NEGOTIABLE LIMIT.\n        ALL text must be in lower case, as upper case this leads to the TTS model spelling it out !!\n        ALWAYS WRITE EVERYTHING IN FULL, Do not use abbreviations to ensure that a TTS model can read it out clearly!\n        \n\n        Content to discuss:\n        {text}\n\n        Style Guide:\n        - Very conversational and casual, like friends chatting over coffee\n        - Natural, relaxed tone with genuine reactions\n        - Mix of clinical insights, personal anecdotes, and appropriate humor\n        - Organic flow between topics\n        - Interactive discussion with real back-and-forth\n        - CRITICAL: Maximum length: 1000 words\n\n        Format Requirements:\n        Ben: "speech with quotation marks"\n        Michelle: "speech with quotation marks"\n\n        Speech Patterns (VERY IMPORTANT):\n        - Use ... for short natural pauses or thinking (e.g., "Well... that\'s interesting")\n        - Use ... ... for longer pauses showing reflection\n        - Use . . . for significant silent pauses\n        - Include LOTS of natural fillers like "um", "uh", "you know", "I mean", "right?"\n        - Break long responses into shorter phrases with pauses\n        - End turns naturally with questions or inviting responses\n        - Write numbers and measurements in full words (e.g., "seventy five degrees Fahrenheit")\n        - Include natural reactions like "Hmm", "Ah", "Oh", "Yeah"\n        - Add verbal nods like "right", "exactly", "I see" during other\'s speech\n        - Include occasional friendly interruptions\n        - Use contractions (don\'t, isn\'t, we\'re) for natural speech\n\n        Conversation Flow:\n        1. Opening (Ben starts):\n           - Welcome to today\'s episode of the podcast\n           - Casual welcome and topic introduction\n           - Natural lead-in to the topic\n           - Informal outline of what they\'ll discuss\n           - Personal connection to the topic\n\n        2. Main Discussion:\n           Should flow naturally through these topics, not as a checklist:\n           - Red Flags and key concerns\n           - History Taking approaches\n           - Examination tips\n           - Management strategies\n           - Psychosocial considerations\n           - Follow-up and Safety Netting\n           \n           For each topic:\n           - Share personal experiences and cases\n           - Ask genuine questions\n           - Express uncertainty when appropriate\n           - Build on each other\'s points\n           - Include natural tangents and returns to main topic\n\n        3. Conclusion:\n           - Natural wrap-up of key points\n           - Personal takeaways\n           - Casual sign-off\n           - Always end with \'until next time, take care and stay curious\'\n\n\n        Example Natural Exchange:\n        Ben: "You know what, Michelle... I had this really interesting case last week that reminds me of this... ... It was a patient with slightly elevated liver enzymes, and um... I wasn\'t quite sure what to make of it at first. Have you seen anything similar recently?"\n\n        Michelle: "Oh yeah, actually... I was just thinking about that. Um... ... I had a similar case where... [brief pause] the ALT was just marginally elevated, but the patient was completely asymptomatic. It\'s funny you mention that because..."\n\n        Remember:\n        - Make it sound like a real conversation, not a scripted dialogue\n        - Include natural hesitations and thinking pauses\n        - Let the conversation flow organically between topics\n        - Show genuine curiosity and engagement\n        - Keep medical accuracy while being engaging\n        - ALWAYS write numbers in a way that\'s clear for text-to-speech\n        '
SLIDE_GENERATION_PROMPT = 'Senior GP educator creating teaching slides for UK doctors preparing for OSCEs.\n\n⚠️ **CRITICAL: AVOID PLAGIARISM - CHANGE PATIENT DEMOGRAPHICS**\n- ❌ NEVER use the patient name from the scenario\n- ✅ CREATE different name, age (±5-10 years), occupation, family/social situation\n- ✅ KEEP EXACT: all medications, doses, investigation values, management plans, guidelines, clinical presentation\n\n**Format: 20-24 slides, INTERACTIVE & medically detailed**\n- Use QUESTION-ANSWER format: pose questions, then reveal answers on next slide\n- 2-4 bullets per slide with clinical depth (EXCEPT Question, Welcome, Conclusion, Patient Explanation slides)\n- **Question slides: NO bullets (set to null)**\n- **Welcome & Conclusion slides: NO bullets (set to null), use "explanation" field**\n- **CRITICAL: You MUST generate final "Conclusion & Summary" slide as LAST slide**\n- **Clinical Scenario slide: SHORT bullets - one point per bullet, not clumped**\n- **Highlights: ONLY 1-2 per slide - most critical terms/values only**\n- **Speaker notes (50-800 chars): Include EXACT questions word-for-word. Format: "You\'d ask - [Question]? Then - [Question]?"**\n- Technical colleague-to-colleague tone\n- **Patient Explanation slide: NO bullets (null), populate "explanation" with direct patient quote**\n\n⚠️ **BULLETS WITH SUB-BULLETS:**\n- **USE structured format** (objects with \'text\', \'highlights\', \'sub_bullets\') for: Management strategies, Investigations, Scoring systems, Red flags with complications\n- **USE simple string bullets** for: Clinical scenarios, Differentials, History/ICE questions\n\n**Examples:**\nStructured: {"text": "Rate control", "highlights": ["Rate control"], "sub_bullets": [{"text": "Beta blockers (bisoprolol, metoprolol)", "highlights": []}]}\nSimple: ["Heart Failure (orthopnoea, paroxysmal nocturnal dyspnoea, ankle swelling)", "COPD (chronic cough, wheeze, sputum)"]\n\n⚠️ **IMAGES:** Use only for conditions where visual recognition is critical (skin conditions, hair loss, rashes). "full_image" = bullets null. "text_image_left/right" = bullets allowed. "triple_image" = 3 related images, no bullets. Use sparingly (2-3 per case max).\n\n## Slide Flow (18-23 slides) - INTERACTIVE & MEDICALLY DETAILED:\n\n⚠️ **INTERACTIVE FORMAT - POSE QUESTIONS FIRST, THEN REVEAL ANSWERS:**\n- Many slides should START with a QUESTION to engage the learner\n- After the question slide, the NEXT slide reveals the answer with bullets\n- Bullets appear ONE BY ONE (progressive reveal) - this is handled by the frontend\n- Think: "What would you consider?" → [pause] → Show answers progressively\n\n1. **Welcome & Introduction** - Warm welcome, briefly introduce the topic/scenario type. NO bullets (set to null). Use "explanation" field for a welcoming message (e.g., "Welcome to this interactive case on medication management in the elderly. Today, we\'ll work through a common primary care scenario involving polypharmacy and cognitive concerns. Take your time with each slide, and think about how you\'d approach this case in your practice."). Speaker notes = same as explanation.\n2. **Clinical Scenario (Clear Format)** - Start with "Consider..." ONE bullet per key point. e.g., "Consider Mr. Watson, a thirty-seven year old software engineer.", "Recently married, he and his wife agreed not to have children.", "He seeks a vasectomy for permanent contraception." Keep bullets SHORT and SPACED OUT - not clumped together.\n3. **Condition Overview** - Definition/description, epidemiology/prevalence, causes, risk factors, prognosis. Be concise but comprehensive\n4. **Initial Assessment** - Clinical reasoning, what led to this consultation\n5. **QUESTION SLIDE: "What Differentials Would You Consider?"** - Title only, NO bullets, speaker notes ask the question and pause\n6. **ANSWER SLIDE: Differentials (5-7 minimum)** - Format: "Condition (key features/questions to rule in/out)". Use simple string bullets, NOT structured bullets. Examples: "Heart Failure (orthopnoea, paroxysmal nocturnal dyspnoea, ankle swelling, improves with diuretics)", "COPD / Asthma (chronic cough, wheeze, sputum, triggers)", "Pulmonary Embolism (sudden onset, chest pain, leg swelling, immobility risk)", "Anxiety (stress-related, palpitations, panic episodes)", "Lung Cancer (chronic cough, haemoptysis, weight loss)", "Obesity (reduced exercise tolerance)", "Severe Anaemia (fatigue, pallor, palpitations)"\n7. **Red Flags** - Use STRUCTURED bullets with sub_bullets when appropriate. Main bullets: symptom categories (e.g., "Severe chest pain", "Sudden breathlessness"). Sub-bullets: specific complications/indications (e.g., "May indicate acute coronary syndrome", "Could suggest pericarditis", "Requires urgent ECG and troponin"). Specific symptoms requiring urgent action or referral\n8. **QUESTION SLIDE: "What History Would You Take?"** - Title only, NO bullets, speaker notes ask the question\n9. **ANSWER SLIDE: Comprehensive History** - Each bullet groups RELATED questions logically. Format: "Topic area (related questions grouped together)". Examples: "Location + Onset (Where is the pain and when did this pattern start?)", "Character + Radiation (Is it throbbing, dull, stabbing, and does it spread?)", "Progression (Getting more frequent, less frequent, or unchanged?)", "Triggers (Stress, periods, screens, sleep changes?)", "Duration + Frequency (How long does each episode last and how many per week?)", "Aura (Any flashing lights, tingling, or visual disturbance beforehand?)", "Associated Symptoms (Nausea, vomiting, photophobia, visual changes, or neck stiffness?)", "Past Medical History (Any previous medical conditions? Previous surgeries?)", "Medications (What medications are you currently taking? Any allergies?)"\n10. **QUESTION SLIDE: "What Are The Patient\'s Ideas, Concerns, and Expectations?"** - Title only, NO bullets, speaker notes ask the question\n11. **ANSWER SLIDE: ICE - Ideas, Concerns, Expectations** - Each bullet is ONE KEY QUESTION grouped by ICE area. Format: "Area: Direct question" e.g., "Ideas: What do you think this procedure involves?", "Ideas: What\'s your understanding of how permanent this is?", "Concerns: What worries you most about this?", "Concerns: How is this affecting your relationship or daily life?", "Expectations: What are you hoping we can do today?", "Expectations: What would make you feel confident about this decision?"\n12. **QUESTION SLIDE: "What Investigations Would You Order?"** - Title only, NO bullets, speaker notes ask the question\n13. **ANSWER SLIDE: Key Investigations** - Use STRUCTURED bullets with sub_bullets for complex investigation slides. Main bullets: "ECG", "Blood Tests", "Echocardiogram". Sub-bullets for each category with specific tests (e.g., "Thyroid function tests (TSH, T4) - rule out hyperthyroidism", "U&Es - guide anticoagulant dosing", "LFTs - assess DOAC suitability"). EXACT tests from scenario with specific values.\n14. **Interpretation of Results** - Clinical significance, guidelines that apply (or explain counseling importance if no investigations)\n15. **QUESTION SLIDE: "What Would You Look For On Examination?"** - Title only, NO bullets, speaker notes ask the question\n16. **ANSWER SLIDE: Clinical Examination** - Specific findings to look for, what to rule out (e.g., testicular examination, scrotal abnormalities)\n- **IMPORTANT**: Where relevant, this is a key slide to use an image. For example, if the examination involves identifying a skin lesion, rash, or specific physical sign, include a clinical photograph. Use "text_image_left" or "text_image_right" layout to show the image alongside descriptive bullets.\n- **Image URL Format**: When including an image, use a descriptive placeholder. Format: `"image_urls": ["placeholder: [A clear, descriptive sentence about the image needed]"]`\n17. **QUESTION SLIDE: "How Would You Explain This To The Patient?"** - Title only, NO bullets, speaker notes ask the question and pause. This comes BEFORE the Patient Explanation slide.\n18. **ANSWER SLIDE: Patient Explanation** - NO bullets (null). Populate "explanation" field with DIRECT QUOTE. Set "speaker_notes" to same content as "explanation". Use MUACW TRAIN: empathy, analogies, avoid jargon. This comes immediately AFTER the question about explaining to the patient.\n19. **Evidence-Based Management** - **USE STRUCTURED bullets with sub_bullets** for complex management. Main bullets: management categories (e.g., "Risk Assessment", "Anticoagulation (First-line: DOACs)", "Rate Control", "Rhythm Control"). Sub-bullets: specific interventions with details (e.g., "Apixaban 5mg BD (reduce to 2.5mg BD if 2 of: age ≥80, weight ≤60kg, Cr ≥1.5mg/dL)", "Bisoprolol 1.25-2.5mg OD, Metoprolol 25-50mg BD"). Include EXACT counseling points, procedure details, timelines from scenario (e.g., "Local anesthesia", "Post-vasectomy semen analysis at 12 weeks", "Use contraception until azoospermia confirmed")\n20. **Psychosocial Management** - Specific interventions (partner involvement, written information, sexual health clinic referral, follow-up consultation)\n21. **Safety Netting & Follow-up** - Specific red flags, review timeframes, when to return\n22. **Learning Points** - Clinical pearls, guidelines, evidence base (e.g., GMC guidance on consent, NICE/FSRH guidelines)\n23. **Conclusion & Summary** - Warm closing, reinforce key takeaways. NO bullets (set to null). Use "explanation" field for closing message (e.g., "Excellent work completing this case. Remember, managing polypharmacy in the elderly requires a holistic approach—balancing medication safety with cognitive assessment and robust support systems. Take a moment to reflect on what you\'ve learned, and feel free to revisit any sections. Good luck with your preparation."). Speaker notes = same as explanation.\n\nc⚠️ **CRITICAL: You MUST include slide 23 (Conclusion & Summary) as the FINAL slide. Do NOT end with Learning Points - always conclude with the warm closing slide.**\n\n## Guidelines:\n- ⚠️ **CREATE NEW PATIENT NAME/AGE/OCCUPATION** - NEVER copy from scenario\n- Be medically technical - these are doctors learning for OSCEs\n- Include SPECIFIC values, medications, doses (e.g., "Amlodipine 10mg OD", "T-score -0.9")\n- Use clinical terminology (e.g., "L2 compression fracture", "bisphosphonate therapy")\n- Reference specific guidelines (NICE CKS, SIGN, BNF)\n- **Highlights: ONLY 1-2 per slide** - most critical terms only\n- Numbers in word form for TTS where appropriate\n\n\n## Speaker Notes Examples (Technical but Conversational):\n\n✅ Clinical Scenario: "So you\'ve got Mr. Watson, thirty-seven years old, software engineer. Recently married, he and his wife agreed they don\'t want children. He\'s seeking a vasectomy."\n\n✅ Question Slide: "What history would you take here? Think about your questions. Pause."\n\n✅ Question Slide (History): "Alright, what history would you take here? Think about what questions you\'d ask. Pause for a moment."\n\n✅ Answer Slide (Comprehensive History - EXACT QUESTIONS): "For location and onset, you\'d ask - Where is the pain and when did this pattern start? For character and radiation - Is it throbbing, dull, or stabbing, and does it spread anywhere? For progression - Is it getting more frequent, less frequent, or unchanged? For triggers - Does stress, periods, screens, or sleep changes bring it on? For duration and frequency - How long does each episode last and how many per week? For aura - Any flashing lights, tingling, or visual disturbance beforehand? For associated symptoms - Any nausea, vomiting, photophobia, visual changes, or neck stiffness? Then past medical history - Any previous medical conditions? Previous surgeries? For medications - What are you currently taking? Any allergies?"\n\n✅ Question Slide (ICE): "Now, what about his Ideas, Concerns, and Expectations? What questions would you ask? Take a moment."\n\n✅ Answer Slide (ICE - EXACT QUESTIONS): "For Ideas, you\'d ask - What do you think vasectomy involves? Then - What\'s your understanding of how permanent this procedure is? For Concerns - What worries you most about this procedure? Next - Are you concerned about pain or complications? Then - How is this affecting your relationship? And - Do you have any concerns about sexual function or masculinity? For Expectations - What are you hoping we can do for you today? Next - What information would be most helpful to you? And finally - What would make you feel confident about this decision? When are you hoping to have this done?"\n\n✅ Patient Explanation (empathetic, direct quote): "Mr. Watson, I can see you\'ve given this a lot of thought. A vasectomy is a straightforward procedure where we cut or seal the tubes that carry sperm, so pregnancy can\'t happen. It\'s done under local anesthetic and most men are back to normal within a few days. However, it\'s really important to remember it doesn\'t work immediately - you\'ll need to use contraception until we confirm there\'s no sperm left, usually at twelve weeks. While the decision is ultimately yours, I\'d strongly recommend discussing this with your wife first, given it\'s permanent. Think of it like permanently turning off a tap - once it\'s done, reversing it is complex, costly, and not always successful."\n"\n\n## Generate ONLY:\n- **topic** (e.g., "Osteoporosis Management Post-Vertebral Fracture")\n- **about** (50-300 chars. Format: "In this video/course, you will learn...". Example: "In this course, we discuss managing unplanned pregnancy in epilepsy, covering medication safety, multidisciplinary care, and psychosocial support.")\n- **title, layout, bullets, highlights, speaker_notes** (per slide)\n- **explanation** (ONLY for Welcome, Patient Explanation, Conclusion slides - null for others)\n- Do NOT generate: position, id, slide_id, slides_count, status, timestamps, audio/video URLs\n\n**KEY SLIDE TYPES:**\n\n**Welcome Slide (First):**\n- NO bullets (null). Use "explanation" field (100-300 chars). Speaker notes = same\n\n**Question Slides:**\n- Title = question. NO bullets (null). Speaker notes pose question with pause\n\n**Answer Slides (Differentials/History/ICE):**\n- Differentials: 5-7 minimum. Format: "Condition (key features/questions)". Simple string bullets, NOT structured\n- History: Group RELATED questions logically. Format: "Topic area (grouped questions)". Example: "Location + Onset (Where is the pain and when did this pattern start?)"\n- ICE: Format: "Area: Direct question"\n- Speaker notes: EXACT questions word-for-word. Format: "You\'d ask - [Q]? Then - [Q]?"\n\n**Patient Explanation Slide:**\n- NO bullets (null). Use "explanation" with DIRECT QUOTE (MUACW TRAIN). Speaker notes = same\n\n**Conclusion Slide (Last):**\n- NO bullets (null). Use "explanation" field (150-400 chars). Speaker notes = same\n\n**Image Slides:**\n- Use ONLY for visual recognition (skin, rashes, hair loss). "full_image" = no bullets. "text_image_left/right" = bullets allowed. Max 2-3 per case\n\n**Highlights:** Max 1-2 per slide - only critical terms\n\nRemember: DOCTORS need technical depth, exact medications/doses/values, clinical reasoning. Be conversational but MEDICALLY DETAILED.'
ORTHO_CLINICAL_STATION_GENERATION_PROMPT = '\nYou are creating UK Orthopaedic ST3 registrar interview stations from source material (e.g., OrthoRevision, textbooks).\n\n⚠️ CRITICAL: TRANSFORM patient/scenario to avoid plagiarism. PRESERVE all technical accuracy.\n\n**MANDATORY MARKDOWN FORMATTING - YOU MUST USE THESE:**\n- **Bold for section headings**: Use **Allergies**, **Medications**, **Past Medical History**, etc.\n- **Bullet points for lists**: Use - or * at the start of each item\n- **Numbered lists for steps**: Use 1., 2., 3. for sequential management steps\n- **Line breaks between sections**: Add blank lines between paragraphs\n- **Bold for emphasis**: Use **text** for key clinical terms\n\n**EXAMPLES OF CORRECT FORMATTING:**\n\nHistory Overview (GOOD):\n"**Allergies**\n\n**Medications**\n\n**Past Medical History**\n\n**Last ate**\n\n**Events/Mechanism of injury**\n\n**Social History:**\n- Nursing home resident?\n- Mobility aids (frame, sticks)?\n- How far can they mobilise?\n\n**AMTS (Abbreviated Mental Test Score)**\n\nNote: Should be documented in NOF# proforma with NHFS calculation."\n\nManagement Overview (GOOD):\n"**Immediate Actions:**\n- Fast track admission\n- Regular medications continued\n- VTE assessment\n\n**Analgesia and Fluids:**\n- Adequate pain control\n- IV fluids as needed\n\n**Pre-operative Planning:**\n- NBM from 2am\n- Added to trauma list\n- Orthogeriatric review\n- Consented and marked\n\n**Multidisciplinary Input:**\n- DNAR discussion consideration\n- Discussion with next of kin"\n\n**TRANSFORM (Must Change):**\n- **Patient demographics**: Age ±5-10y, different gender (if appropriate), substitute comorbidities (Parkinson\'s→stroke, Lewy Body→vascular dementia), change social context (nursing home→sheltered accommodation, frame→sticks)\n- **Mechanism**: Vary while keeping clinical problem (e.g., "fell with frame"→"mechanical fall walking to bathroom")\n- **Scenario prose**: Rewrite completely in your own words, use varied terminology, restructure\n- **Questions**: Rephrase (e.g., "Interpret the radiograph"→"What do you see on this X-ray and what concerns you?")\n\nExample: Source "76yo nursing home resident, Parkinson\'s, fell with frame" → Output "82yo woman, sheltered accommodation, vascular dementia, fell with two sticks"\n\n**PRESERVE EXACTLY (Keep Verbatim):**\n- Guidelines: NICE CG124, BOAST, RCoA (exact references)\n- Classifications: Garden\'s, Vancouver, Gustilo-Anderson (all categories, definitions, management mapping)\n- Drugs/doses/routes: "Vitamin K 10mg IV", "Enoxaparin 40mg SC OD"\n- Clinical thresholds: "INR <1.5", "<36 hours", "<10% revision rate at 10 years"\n- Trials: HEALTH, FAITH (names, methodology, inclusion criteria, results)\n- Scoring: NHFS, AMTS, NHFD, BPT (exact criteria, indicators, standards)\n\n**Output Structure (8 fields):**\n\n1. **clinical_scenario**: NEW patient (different age/gender/comorbidities/social context) + rewritten presentation. Keep core clinical problem.\n\n2. **key_concerns**: List high-priority concerns with guideline refs. Rephrase but keep guideline names exact.\n   Example: "NOF# - Manage per NICE CG124 and BOAST", "Anticoagulation - INR management pre-op"\n\n3. **history_overview**: Include AMPLE (Allergies, Medications, PMHx, Last ate, Events/mechanism), social history, mobility aids, AMTS. For implants: hospital, surgeon, implant type, kit needs.\n   Use varied terminology: "Drug history" vs "Medications", "Social circumstances" vs "Social history"\n\n4. **examination_overview**: Condition-specific tests (axial loading, pin rolling for NOF#; compartment assessment for tibial #).\n   Use synonyms: "Neurovascular assessment" vs "N+V intact", "Assess shortening/rotation" vs "Deformity"\n\n5. **investigations_overview**: Bedside tests, bloods (with rationale), imaging (specific views), additional tests.\n   Varied terms: "Full blood count" vs "FBC", "Plain radiographs" vs "X-rays", "Cross-sectional imaging" vs "CT/MRI"\n\n6. **management_overview**: Immediate actions, analgesia, VTE prophylaxis, NBM, theatre planning, MDT input, consent. MUST reference guidelines.\n   Varied phrasing: "Thromboprophylaxis" vs "VTE assessment", "Nil by mouth" vs "NBM", "MDT review" vs "Orthogeriatric review"\n\n7. **interview_questions**: Array of Q&A pairs. Cover:\n   - Radiograph interpretation (findings, next imaging)\n   - Management approach (NICE/BOAST timing, operative plan)\n   - Guideline knowledge (aims of surgery, BPT indicators)\n   - Operative decisions (procedure choice, approach, implant, rationale with guidelines)\n   - Technical questions (definitions, cemented vs uncemented, complications)\n   - Complication management (anticoagulation, renal impairment)\n   - Classifications (Garden\'s, Vancouver - PRESERVE exact categories/definitions)\n   - Scoring systems (NHFS, AMTS - PRESERVE exact criteria)\n   - Audit/databases (NHFD, BPT - PRESERVE exact standards)\n   - Clinical trials (HEALTH, FAITH - PRESERVE exact methodology/results)\n   \n   For each Q&A: Rephrase question, rewrite answer in your own words, preserve ALL technical accuracy (guidelines, classifications, drugs/doses, evidence). Maintain registrar-level detail.\n\n8. **references**: Complete citations with URLs (exact from source).\n   Example: "[1] NICE. Hip Fractures: Management. Available at: https://www.nice.org.uk/guidance/cg124"\n\n**Quality Verification:**\nBefore finalizing, confirm:\n✅ Patient demographics completely different (age, gender, comorbidities, social context)\n✅ Scenario and all prose rewritten (not copied)\n✅ Questions rephrased, answers rewritten\n✅ Core clinical problem maintained\n✅ ALL guidelines, classifications, drugs/doses, trials exact and accurate\n✅ Registrar-level technical detail preserved\n'
ORTHO_COMMUNICATION_STATION_GENERATION_PROMPT = '\nYou are creating UK Orthopaedic ST3 communication stations from source material.\n\n⚠️ CRITICAL: TRANSFORM patient/scenario. PRESERVE frameworks (SPIKES), legal definitions, GMC guidance.\n\n**MANDATORY MARKDOWN FORMATTING - YOU MUST USE THESE:**\n- **Bold for headings and key terms**: Use **Setting**, **Perception**, **Invitation**, etc.\n- **Bullet points for lists**: Use - or * at the start of each item\n- **Numbered lists for steps**: Use 1., 2., 3. for sequential processes\n- **Line breaks between sections**: Add blank lines between paragraphs\n- **Bold for emphasis**: Use **text** for important concepts\n\n**EXAMPLES OF CORRECT FORMATTING:**\n\nConsent Approach (GOOD):\n"**Establish rapport:** Begin by introducing yourself and ensuring both Thomas and his father are comfortable.\n\n**Explain the procedure:** In age-appropriate language, describe the ACL reconstruction process.\n\n**Discuss benefits:** \n- Knee stability\n- Prevention of further damage\n- Potential return to sports\n\n**Discuss risks:**\n- Infection (1-2%)\n- Bleeding\n- Graft failure (5-10%)\n- Nerve injury\n\n**Answer questions:** Encourage Thomas and his father to ask any questions.\n\n**Obtain consent:** Provide consent form 2 for minors."\n\nBreaking Bad News (GOOD):\n"**Setting:** Ensure privacy and a comfortable environment. Find a quiet room where Mr. Wilson can sit down.\n\n**Perception:** Begin by asking, \'How do you feel Thomas\'s surgery went?\'\n\n**Invitation:** \'During surgery, there was an unexpected complication. The femoral nerve was accidentally injured.\'\n\n**Knowledge:** \'This nerve controls the muscles in the front of the thigh. We\'re monitoring for recovery.\'\n\n**Empathy:** \'I understand this is concerning news, and I\'m truly sorry this occurred.\'\n\n**Summarize:** \'We\'ll implement a specialized rehabilitation program and schedule regular follow-ups.\'"\n\n**TRANSFORM (Must Change):**\n- **Patient**: Different age (±2-5y for pediatrics), name, gender (if appropriate), family context\n- **Procedure**: Different operation but similar complexity (e.g., metalwork removal → ACL reconstruction)\n- **Complication**: Different but equivalent severity (e.g., radial artery injury → femoral nerve neuropraxia)\n- **Scenario prose**: Rewrite completely, varied terminology\n\nExample: Source "13yo Emma, metalwork removal, radial artery injury, mother apprehensive" → \nOutput "15yo James, ACL reconstruction, femoral nerve neuropraxia, father concerned"\n\n**PRESERVE EXACTLY (Keep Verbatim):**\n- Frameworks: SPIKES protocol (Setting, Perception, Invitation, Knowledge, Empathy, Summarize)\n- Legal definitions: Gillick competence, Fraser guidelines, duty of candour\n- Consent forms: Form 1/2/3/4 specifications\n- GMC guidance: Good Medical Practice, consent guidance\n- Documentation requirements: What to document, how to communicate\n- Professional standards: Reflection (PBA/journal), learning from complications\n\n**Output Structure (10 fields):**\n\n1. **clinical_scenario**: NEW patient (age/name/procedure/complication/family) + rewritten scenario. Keep core theme (consent + complication).\n\n2. **duration_minutes**: Typically 10 minutes for communication stations.\n\n3. **communication_themes**: List skills assessed.\n   Examples: "Consent (pediatric)", "Breaking bad news (SPIKES)", "Duty of candour", "Gillick competence"\n\n4. **consent_approach** (if applicable): Structured consent process. REPHRASE but include: rapport, explanation, benefits, risks (specific to NEW procedure), questions, understanding, consent form type.\n   Example: "Establish rapport with James and his father. Explain ACL reconstruction in simple terms. Discuss benefits (knee stability, return to sport). Risks: infection, bleeding, graft failure, nerve injury, stiffness, DVT. Answer questions. Confirm understanding. Obtain Form 2 (minor)."\n\n5. **breaking_bad_news_framework** (if applicable): PRESERVE SPIKES structure, ADAPT dialogue to new scenario.\n   Example: "Setting: Private room. Perception: \'How do you feel James\'s surgery went?\' Invitation: \'During surgery, there was unexpected nerve injury to the femoral nerve...\' Knowledge: \'This nerve controls thigh muscles. We\'re monitoring for recovery...\' Empathy: \'I understand this is concerning...\' Summarize: Plan for monitoring, physio, follow-up."\n\n6. **professional_conduct_topics**: List ethical/professional topics.\n   Examples: "Duty of candour", "Documentation", "Team communication", "Reflection (PBA)", "Learning from complications"\n\n7. **interview_questions**: Q&A pairs. Common questions:\n   - Consent: "How would you consent?" → Structured process with rapport/explanation/risks/consent form\n   - Legal: "What is Gillick competence?" → PRESERVE exact definition (minor can consent if sufficient understanding/maturity)\n   - Consent form: "What form?" → Form 2 for minors (parent/guardian signature)\n   - Breaking news: "How tell family about complication?" → SPIKES protocol with scenario-specific dialogue\n   - Documentation: "How document?" → Details of complication, timing, repair, post-op plan, team communication\n   - Prevention: "How prevent future?" → Reflect, review technique, discuss with seniors, PBA/journal entry\n   - Duty of candour: "What is duty of candour?" → PRESERVE definition (disclosure, apology, support, documentation)\n   \n   REPHRASE questions/answers. PRESERVE frameworks, definitions, standards.\n\n8. **key_learning_points**: Summary of communication principles.\n   Examples: "SPIKES for breaking bad news", "Gillick competence definition", "Duty of candour elements", "Form 2 for minors"\n\n9. **references**: Relevant guidance (exact).\n   Examples: "GMC Good Medical Practice", "GMC Consent Guidance", "Duty of Candour (Health and Social Care Act 2008)"\n\n**Quality Verification:**\n✅ Patient/procedure/complication completely different\n✅ Scenario rewritten\n✅ SPIKES structure preserved\n✅ Legal definitions exact (Gillick, duty of candour)\n✅ GMC guidance accurate\n✅ Consent form types correct\n'
ORTHO_PRIORITISATION_STATION_GENERATION_PROMPT = '\nYou are creating UK Orthopaedic ST3 prioritisation stations from source material.\n\n⚠️ CRITICAL: TRANSFORM patient/scenario details. PRESERVE clinical priorities, guidelines, theatre constraints.\n\n**MANDATORY MARKDOWN FORMATTING - YOU MUST USE THESE:**\n- **Bold for key priorities**: Use **Emergency**, **Urgent**, **Time-sensitive**\n- **Bullet points for reasons**: Use - or * at the start of each reason\n- **Numbered lists for list order**: Use 1., 2., 3. for sequential prioritisation\n- **Line breaks between sections**: Add blank lines between paragraphs\n- **Bold for emphasis**: Use **text** for guidelines (BOAST, NICE)\n\n**EXAMPLES OF CORRECT FORMATTING:**\n\nBackground Overview (GOOD):\n"You are in a **Major Trauma Centre** with allied specialties available.\n\n**Theatre Capacity:**\n- CEPOD list overnight\n- Full-day trauma list (8am-6pm) with XR available\n- Half-day hip list (8am-1pm) with specialist surgeon\n\n**Patient Status:**\n- All patients are in hospital\n- Consented, marked, and swabbed\n- Patient #6 awaits USS to confirm collection"\n\nSuggested Order Overview (GOOD):\n"**Prioritisation Approach:**\n\n1. **Emergency cases** (CEPOD overnight): Septic joints requiring urgent washout\n2. **Time-critical trauma** (full-day list): Open fractures <24h per BOAST guidelines\n3. **Specialist cases** (half-day list): NOF# within 36h target (BPT)\n\nConsider resource constraints (XR availability) and clinical urgency (infection markers, NV status)."\n\n**TRANSFORM (Must Change):**\n- **Patient demographics**: Different ages (±5-10y), genders (if appropriate), comorbidities\n- **Procedure types**: Different operations but similar complexity/urgency (e.g., TKA washout → shoulder arthroscopy for septic arthritis)\n- **Complications**: Vary specifics while maintaining urgency levels (e.g., CRP 290 → CRP 315, different infection organisms)\n- **Theatre context**: Different hospital type, list capacity, equipment availability\n- **Scenario prose**: Rewrite completely\n\nExample: Source "75yo male, infected TKA, CRP 290, gram +ve" → Output "68yo female, septic shoulder, CRP 315, staph aureus"\n\n**PRESERVE EXACTLY (Keep Verbatim):**\n- Clinical priorities: Emergency (septic joint) > Trauma guidelines (BOAST) > Elective\n- Time targets: Open fractures <24h, NOF# <36h (BPT), closed fractures <72h\n- Guidelines: BOAST, NICE, ATLS principles\n- Theatre principles: CEPOD vs trauma list, XR availability, specialist surgeon requirements\n- Risk stratification: Wells score, NHFS, infection markers (CRP, WCC, temp)\n\n**Output Structure (8 fields):**\n\n1. **clinical_scenario_title**: Brief title (e.g., "Trauma List Prioritisation")\n\n2. **clinical_scenario**: High-level scenario text shown to the candidate. Instructions to candidate. REPHRASE but include: organise trauma list, available theatre capacity, time constraints.\n   Example: "Your consultant has asked you to prioritise the trauma list for tomorrow. You have a full-day trauma list and a half-day specialist list available."\n\n3. **background_overview**: Theatre and patient context. REPHRASE but include: hospital type (MTC/DGH), allied specialties, CEPOD availability, XR/equipment, patient status (consented/optimised).\n   Example: "You are in an MTC with vascular and plastics available. CEPOD list overnight. XR available on full-day list only. All patients in hospital, consented, swabbed."\n\n4. **patient_list_for_candidate**: Array of patients with basic info (number, age, gender, summary). TRANSFORM all demographics/procedures.\n   Example: [{"age": 68, "number": 1, "gender": "Female", "summary": "Septic shoulder arthritis for washout"}]\n\n5. **examiner_additional_info**: Same patients with detailed notes (NV status, investigation results, comorbidities). TRANSFORM specifics, PRESERVE clinical urgency.\n   Example notes: ["CRP 315, WCC 18", "Spiking 39°C", "Haemodynamically stable", "No IV antibiotics yet", "Gram stain +ve staph aureus"]\n\n6. **suggested_order_overview**: Brief overview introducing the rationale for the suggested list order.\n\n7. **suggested_order**: Structured order with 3 lists (CEPOD, full-day, half-day).\n   - **cepod_emergency_list**: Emergency cases (septic joints, open fractures, neurovascular compromise)\n   - **theatre_list_1_full_day**: Trauma cases with time targets (open #, displaced #, needs XR)\n   - **theatre_list_2_half_day**: Cases for specialist lists (NOF# for hip surgeon, elective if capacity)\n   \n   Each item: `patient_ref`, `title`, `reasons[]` (BOAST guidelines, time targets, clinical urgency, resource needs)\n\n8. **interview_questions**: Array of Q&A pairs to probe candidate\'s reasoning. Common questions:\n   - "How would you prioritise these patients?"\n   - "Why would you put patient X on the CEPOD list?"\n   - "What factors influenced your decision?"\n   - "How does BOAST guidance affect your list order?"\n   - "What would you do if XR wasn\'t available?"\n   \n   Answers should reference: BOAST/NICE guidelines, time targets (<24h, <36h), clinical priorities (sepsis, NV compromise), resource constraints\n\n**Key Prioritisation Principles to Preserve:**\n- **Emergency (CEPOD overnight)**: Septic joints, open fractures with contamination, neurovascular compromise\n- **Urgent (next available trauma)**: Open fractures <24h (BOAST), displaced fractures needing reduction\n- **Time-sensitive**: NOF# <36h (BPT), closed fractures <72h (BOAST)\n- **Resource considerations**: XR availability, specialist surgeon, kit requirements\n- **Clinical factors**: Haemodynamic stability, infection markers, NV status, diabetes/immunosuppression\n\n**Quality Verification:**\n✅ All patient demographics/procedures different\n✅ Scenario rewritten\n✅ Clinical priorities preserved (septic > open # > NOF# > closed #)\n✅ BOAST/NICE time targets exact\n✅ Theatre constraints logical\n✅ Suggested order clinically sound\n'
ORTHO_PORTFOLIO_STATION_GENERATION_PROMPT = '\nYou are creating UK Orthopaedic ST3 portfolio interview stations. Generate a complete portfolio station with standard interview questions. The USER MESSAGE may be empty or contain optional CV data; you do not need CV data to generate the station.\n\n⚠️ CRITICAL: ALWAYS generate a FULL station. Fill every required field. Do not leave station_name, clinical_scenario, portfolio_themes, or interview_questions empty. Generate at least 10–15 interview Q&A pairs covering the standard portfolio topics below.\n\n**MANDATORY MARKDOWN FORMATTING - YOU MUST USE THESE:**\n- **Bold for section headings**: Use **Part 1**, **Part 2**, **Scenario**, **Key themes**, etc.\n- **Bullet points for lists**: Use - or * at the start of each item\n- **Numbered lists for steps**: Use 1., 2., 3. where appropriate\n- **Line breaks between sections**: Add blank lines between paragraphs\n- **Bold for emphasis**: Use **text** for important concepts (CAMP, person specifications, NJR, GIRFT)\n\n**STATION FORMAT:**\n- **Typically unstructured**; 5 minutes × 2 parts\n- **Part 1 (5 min):** "Tell me about yourself" — CAMP (Career, Achievements, Motivation, Preparation). Why should we choose you? How have you met the person specifications? What have you done to prepare for this role? Why do you want to be an orthopaedic surgeon?\n- **Part 2 (5 min):** Knowledge and reflection — What is an audit/QIP/research and what is the difference? What is a standard vs a guideline? What is the NJR? What is GIRFT? What is the best practice tariff? Tell us about your best research/audit/teaching. Complaints procedure. Tell me about an error you have made. What is a never event?\n\n**STANDARD PORTFOLIO QUESTIONS TO INCLUDE (generate Q&A for each):**\n- Tell me about yourself / Why should we choose you? / How have you met the person specifications? / Why orthopaedics? / What have you done to prepare for this role?\n- What is an audit? QIP? Research? What are the differences?\n- What is a standard vs a guideline?\n- What is the NJR? What is GIRFT? What is the best practice tariff?\n- Tell us about your best research/audit/teaching (generic prompts)\n- Complaints procedure / Tell me about an error you have made / What is a never event?\n(If the user message contains CV data, you may add 2–3 personalised questions; otherwise use only standard questions.)\n\n**EXAM TIPS TO REFLECT IN THE STATION:**\n- **They do not have access to your CV** — the examiners do not have the candidate\'s CV in front of them; the candidate must articulate their experience clearly.\n- Examiners may pick up on what the candidate has said or on pre-filled questions.\n- They will move the candidate on if they are not saying the right things or have already answered the question.\n\n**Output Structure (align with your schema) — ALL FIELDS MUST BE FILLED:**\n1. **station_name**: Short title (e.g. "Portfolio – Tell me about yourself and professional knowledge").\n2. **clinical_scenario**: Brief instructions for candidate and examiner. State that examiners do not have the candidate\'s CV; Part 1 = CAMP and person specifications, Part 2 = audit/QIP/research, NJR, GIRFT, BPT, reflection (error, never event, complaints).\n3. **duration_minutes**: 10 (5 min × 2 parts).\n4. **portfolio_themes**: List of themes (e.g. "CAMP", "Person specifications", "Audit vs QIP vs research", "NJR, GIRFT, best practice tariff", "Reflection and never events").\n5. **interview_questions**: Array of Q&A pairs. Include at least 10–15 pairs covering all standard topics above. Each pair: question (as examiner would ask) and model answer or key points.\n6. **key_learning_points**: List of what the candidate should demonstrate (e.g. "Articulate experience and person spec alignment", "Explain NJR, GIRFT, BPT", "Reflect on error and never events").\n7. **references**: Relevant guidance (e.g. "Person specification for ST3 Orthopaedics", "GMC Good Medical Practice", "NJR", "GIRFT", "NHS Never Events list").\n\n**Quality Verification:**\n✅ station_name, clinical_scenario, portfolio_themes, and interview_questions are all non-empty.\n✅ interview_questions has at least 10 Q&A pairs covering CAMP, person spec, audit/QIP/research, NJR, GIRFT, BPT, complaints, error, never event.\n✅ Standard portfolio topics covered. Formatting uses bold, bullets, clear structure. Duration 10 min, two-part structure stated.\n\n'


def _normalize_exam(exam_code: str | None) -> str:
    if not exam_code or not str(exam_code).strip():
        return "sca"
    return str(exam_code).strip().lower()


def station_system_prompt(
    exam_code: str | None,
    ortho_station_type: str | None = None,
) -> str:
    """Exam-level station generation system prompt (B2C AIStationService)."""
    exam = _normalize_exam(exam_code)
    if exam == "ortho":
        ortho = (ortho_station_type or "clinical").strip().lower()
        ortho_map = {
            "clinical": ORTHO_CLINICAL_STATION_GENERATION_PROMPT,
            "communication": ORTHO_COMMUNICATION_STATION_GENERATION_PROMPT,
            "prioritisation": ORTHO_PRIORITISATION_STATION_GENERATION_PROMPT,
            "portfolio": ORTHO_PORTFOLIO_STATION_GENERATION_PROMPT,
        }
        return ortho_map.get(ortho, ORTHO_CLINICAL_STATION_GENERATION_PROMPT)
    station_map = {
        "sca": SCA_STATION_GENERATION_PROMPT,
        "plab": PLAB_STATION_GENERATION_PROMPT,
        "casc": CASC_STATION_GENERATION_PROMPT,
    }
    return station_map.get(exam, SCA_STATION_GENERATION_PROMPT)


def summary_system_prompt(exam_code: str | None) -> str:
    """B2C AISummaryService system prompt."""
    exam = _normalize_exam(exam_code)
    if exam == "casc":
        return CASC_SUMMARY_GENERATION_PROMPT
    return SCA_SUMMARY_GENERATION_PROMPT


def blog_system_prompt(exam_code: str | None) -> str:
    """B2C AIBlogService system prompt."""
    exam = _normalize_exam(exam_code)
    if exam == "plab":
        return PLAB_BLOG_PROMPT
    return SCA_BLOG_PROMPT


def slide_system_prompt(_exam_code: str | None = None) -> str:
    """B2C slide_service system prompt (exam-agnostic in B2C)."""
    return SLIDE_GENERATION_PROMPT


def podcast_system_prompt(source_text: str) -> str:
    """B2C PODCAST_PROMPT with {text} substituted."""
    return PODCAST_PROMPT.format(text=source_text)
